1	package com.loja.checkout;
2	
3	import com.loja.checkout.clube.NivelClube;
4	import com.loja.checkout.cupom.ContextoCupom;
5	import com.loja.checkout.cupom.Cupom;
6	import com.loja.checkout.entrega.ModalidadeEntrega;
7	import com.loja.checkout.pagamento.FormaPagamento;
8	import com.loja.checkout.pagamento.ResultadoPagamento;
9	import com.loja.checkout.regiao.Regiao;
10	import org.springframework.stereotype.Service;
11	
12	import java.math.BigDecimal;
13	import java.math.RoundingMode;
14	import java.util.List;
15	import java.util.Map;
16	import java.util.function.Function;
17	import java.util.stream.Collectors;
18	
19	@Service
20	public class CheckoutService {
21	
22	    private final Map<String, ModalidadeEntrega> modalidades;
23	    private final Map<String, Cupom> cupons;
24	    private final Map<String, NivelClube> niveis;
25	    private final Map<String, FormaPagamento> formasPagamento;
26	
27	    public CheckoutService(List<ModalidadeEntrega> modalidades,
28	                           List<Cupom> cupons,
29	                           List<NivelClube> niveis,
30	                           List<FormaPagamento> formasPagamento) {
31	        this.modalidades = modalidades.stream().collect(Collectors.toMap(ModalidadeEntrega::codigo, Function.identity()));
32	        this.cupons = cupons.stream().collect(Collectors.toMap(Cupom::codigo, Function.identity()));
33	        this.niveis = niveis.stream().collect(Collectors.toMap(NivelClube::codigo, Function.identity()));
34	        this.formasPagamento = formasPagamento.stream().collect(Collectors.toMap(FormaPagamento::codigo, Function.identity()));
35	    }
36	
37	    public ResumoResponse calcular(ResumoRequest req) {
38	        validarItens(req.itens());
39	
40	        NivelClube clube = buscar(niveis, req.nivelClube(), "NIVEL_CLUBE_INVALIDO");
41	        Regiao regiao = buscarRegiao(req.regiao());
42	        ModalidadeEntrega entrega = buscar(modalidades, req.modalidadeEntrega(), "MODALIDADE_INVALIDA");
43	
44	        BigDecimal pesoTotal = calcularPesoTotal(req.itens());
45	        if (!entrega.disponivel(pesoTotal)) {
46	            throw new CheckoutException("MODALIDADE_INDISPONIVEL");
47	        }
48	
49	        Cupom cupom = null;
50	        if (req.cupom() != null && !req.cupom().isBlank()) {
51	            cupom = buscar(cupons, req.cupom(), "CUPOM_INVALIDO");
52	        }
53	
54	        FormaPagamento pagamento = buscar(formasPagamento, req.formaPagamento(), "FORMA_PAGAMENTO_INVALIDA");
55	        int parcelas = req.parcelas() != null ? req.parcelas() : 1;
56	        if (!pagamento.parcelasValidas(parcelas)) {
57	            throw new CheckoutException("PARCELAMENTO_INVALIDO");
58	        }
59	
60	        BigDecimal subtotal = calcularSubtotal(req.itens());
61	        BigDecimal frete = entrega.calcularFrete(pesoTotal);
62	        if (clube.freteGratis()) {
63	            frete = BigDecimal.ZERO.setScale(2);
64	        }
65	
66	        BigDecimal descontoCupom = BigDecimal.ZERO.setScale(2);
67	        if (cupom != null) {
68	            ContextoCupom ctx = new ContextoCupom(req.itens(), subtotal, frete);
69	            if (!cupom.aplicavel(ctx)) {
70	                throw new CheckoutException("CUPOM_NAO_APLICAVEL");
71	            }
72	            descontoCupom = cupom.calcularDesconto(ctx);
73	        }
74	
75	        BigDecimal seguro = regiao.calcularSeguro(subtotal);
76	        BigDecimal totalPedido = subtotal.subtract(descontoCupom).add(frete).add(seguro);
77	
78	        if (!pagamento.disponivel(totalPedido)) {
79	            throw new CheckoutException("FORMA_PAGAMENTO_INDISPONIVEL");
80	        }
81	
82	        ResultadoPagamento resultado = pagamento.calcular(totalPedido, parcelas);
83	        BigDecimal ajuste = resultado.totalFinal().subtract(totalPedido).setScale(2, RoundingMode.HALF_EVEN);
84	        BigDecimal credito = clube.calcularCredito(subtotal);
85	        boolean brinde = clube.brinde(subtotal);
86	
87	        return new ResumoResponse(
88	                subtotal, descontoCupom, frete, entrega.prazoDias(), seguro,
89	                ajuste, resultado.totalFinal(), parcelas, resultado.valorParcela(),
90	                credito, brinde
91	        );
92	    }
93	
94	    private void validarItens(List<ItemCarrinho> itens) {
95	        if (itens == null || itens.isEmpty()) {
96	            throw new CheckoutException("PEDIDO_INVALIDO");
97	        }
98	        for (ItemCarrinho item : itens) {
99	            if (item.precoUnitario() == null || item.precoUnitario().compareTo(BigDecimal.ZERO) <= 0
100	                    || item.quantidade() == null || item.quantidade() <= 0
101	                    || item.pesoKg() == null || item.pesoKg().compareTo(BigDecimal.ZERO) <= 0) {
102	                throw new CheckoutException("PEDIDO_INVALIDO");
103	            }
104	        }
105	    }
106	
107	    private BigDecimal calcularSubtotal(List<ItemCarrinho> itens) {
108	        BigDecimal subtotal = BigDecimal.ZERO;
109	        for (ItemCarrinho item : itens) {
110	            subtotal = subtotal.add(item.precoUnitario().multiply(BigDecimal.valueOf(item.quantidade())));
111	        }
112	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
113	    }
114	
115	    private BigDecimal calcularPesoTotal(List<ItemCarrinho> itens) {
116	        BigDecimal peso = BigDecimal.ZERO;
117	        for (ItemCarrinho item : itens) {
118	            peso = peso.add(item.pesoKg().multiply(BigDecimal.valueOf(item.quantidade())));
119	        }
120	        return peso;
121	    }
122	
123	    private Regiao buscarRegiao(String codigo) {
124	        if (codigo == null || codigo.isBlank()) {
125	            throw new CheckoutException("REGIAO_INVALIDA");
126	        }
127	        try {
128	            return Regiao.valueOf(codigo);
129	        } catch (IllegalArgumentException e) {
130	            throw new CheckoutException("REGIAO_INVALIDA");
131	        }
132	    }
133	
134	    private <T> T buscar(Map<String, T> mapa, String codigo, String codigoErro) {
135	        if (codigo == null || codigo.isBlank()) {
136	            throw new CheckoutException(codigoErro);
137	        }
138	        T valor = mapa.get(codigo);
139	        if (valor == null) {
140	            throw new CheckoutException(codigoErro);
141	        }
142	        return valor;
143	    }
144	}
