1	package com.loja.checkout.pagamento;
2	
3	import org.springframework.stereotype.Component;
4	
5	import java.math.BigDecimal;
6	import java.math.RoundingMode;
7	
8	@Component
9	public class Cartao implements FormaPagamento {
10	
11	    private static final BigDecimal TAXA_JUROS = new BigDecimal("0.0199");
12	    private static final int PARCELAS_SEM_JUROS = 3;
13	    private static final int PARCELAS_MAX = 12;
14	
15	    @Override
16	    public String codigo() {
17	        return "CARTAO";
18	    }
19	
20	    @Override
21	    public boolean parcelasValidas(int parcelas) {
22	        return parcelas >= 1 && parcelas <= PARCELAS_MAX;
23	    }
24	
25	    @Override
26	    public boolean disponivel(BigDecimal totalPedido) {
27	        return true;
28	    }
29	
30	    @Override
31	    public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
32	        if (parcelas <= PARCELAS_SEM_JUROS) {
33	            BigDecimal valorParcela = totalPedido.divide(BigDecimal.valueOf(parcelas), 2, RoundingMode.HALF_EVEN);
34	            return new ResultadoPagamento(totalPedido, valorParcela);
35	        }
36	
37	        BigDecimal umMaisTaxa = BigDecimal.ONE.add(TAXA_JUROS);
38	        BigDecimal potencia = umMaisTaxa.pow(parcelas);
39	        BigDecimal inversoPotencia = BigDecimal.ONE.divide(potencia, 34, RoundingMode.HALF_EVEN);
40	        BigDecimal denominador = BigDecimal.ONE.subtract(inversoPotencia);
41	        BigDecimal valorParcela = totalPedido.multiply(TAXA_JUROS)
42	                .divide(denominador, 2, RoundingMode.HALF_EVEN);
43	        BigDecimal totalFinal = valorParcela.multiply(BigDecimal.valueOf(parcelas));
44	        return new ResultadoPagamento(totalFinal, valorParcela);
45	    }
46	}
